#include "tablet/span_cache.hpp"
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <random>
#include <csignal>
#include <sys/resource.h>
using namespace engine;
namespace sp=tablet::spans;
namespace d=document;
static void check(bool b,const char* msg){if(!b){std::fprintf(stderr,"FAIL %s\n",msg);std::abort();}}
static auto noStop=[](){return false;};
struct Temp {char path[64]="/tmp/ip-span-test-XXXXXX";Temp(){check(mkdtemp(path)!=nullptr,"temp");}~Temp(){std::filesystem::remove_all(path);}};
static std::string hex(d::Digest v){std::string s;for(auto b:v){char c[3];std::snprintf(c,3,"%02x",b);s+=c;}return s;}
static void hashTest(){d::SourceDigest a,b,c;std::array<uint8_t,3> abc{'a','b','c'};b.update(abc);std::array<uint8_t,1000> block{};block.fill('a');for(int i=0;i<1000;++i)c.update(block);check(hex(a.finish())=="e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","empty SHA");check(hex(b.finish())=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","abc SHA");check(hex(c.finish())=="cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0","million SHA");}
struct Fixture {
    d::Brush brush;std::vector<sp::Packet> packets;uint32_t vertices=0;double dx=8.5,dy=-3.5;
    std::unique_ptr<d::Ink> ink;d::wire::Header header{};sp::Key key{};
    static bool match(uint32_t,float ax,float ay,float bx,float by,float r0,float r1,sp::SpanBounds& box){double pad=2*(std::max(r0,r1)+10);sp::SpanBounds a{std::min(ax,bx)-pad,std::min(ay,by)-pad,std::max(ax,bx)+pad,std::max(ay,by)+pad};box=sp::join(box,a);return true;}
    static bool emit(void* p,const d::ReplaySpan& s){auto& f=*static_cast<Fixture*>(p);if(s.kind!=d::ReplaySpan::Curve&&s.kind!=d::ReplaySpan::Terminal)return true;sp::Packet a{};a.span=s;a.vertices.first=f.vertices;check(s.chords([&](auto... v){match(f.vertices,v...,a.box);f.vertices+=6;return true;}),"reference chords");sp::SpanBounds curve;check(d::spanBounds(s,f.dx,f.dy,curve),"reference bounds");a.box=sp::join(a.box,curve);a.vertices.count=f.vertices-a.vertices.first;f.packets.push_back(a);return true;}
    Fixture(uint64_t seed,size_t n,bool line=false){std::mt19937_64 rng(seed);brush.radiusWorld=2.0f;input::RawInputStroke raw;double x=0,y=0,t=1;for(size_t i=0;i<n;++i){if(line||i%7){x+=line?1.:double(int(rng()%31)-10)/4;y+=line?0.:double(int(rng()%21)-10)/4;}if(line||i%11)t+=.003;raw.push_back({{x,y},t,float(rng()%101)/100,0,0});}ink=std::make_unique<d::Ink>(std::move(raw),brush);check(ink->valid()&&d::wire::header(brush,dx,dy,header),"fixture ink");auto stream=d::CanonicalStream::create(brush).value();check(stream.append(ink->samples,this,emit)&&stream.finish(this,emit),"oracle stream");key.doc[0]=uint8_t(seed);key.id=1;key.geometry=2;d::SourceDigest h;h.update(header);std::array<uint8_t,36> bytes{};for(auto& p:ink->samples){check(d::wire::samples(std::span(&p,1),bytes),"wire");h.update(bytes);}key.digest=h.finish();key.mesh=key.digest;}
};
static bool exact(const sp::Packet& a,const sp::Packet& b){std::array<uint8_t,sp::packetBytes> aa{},bb{};sp::putPacket(aa.data(),a);sp::putPacket(bb.data(),b);return aa==bb;}
static uint64_t comparisons=0,packets=0,reads=0;
static void verify(sp::Cache::Ready& r,Fixture& f,sp::Stats& s,uint64_t seed,int iterations){std::mt19937_64 rng(seed);auto emit=[&](const sp::Packet& a){check(a.span.ordinal<f.packets.size()&&exact(a,f.packets[a.span.ordinal]),"packet bytes");};for(int i=0;i<iterations;++i){const auto start=uint32_t(rng()%f.packets.size()),n=uint32_t(std::min<size_t>(1+rng()%128,f.packets.size()-start));uint32_t next=start;auto output=[&](const sp::Packet& a){emit(a);check(a.span.ordinal==next++,"ordinal sequence");};auto w=sp::direct(r.file,r.manifest,start,n,s,noStop,output);check(next==start+n&&w.pages<=20,"bounded direct read");reads+=w.pages;packets+=n;++comparisons;auto& b=f.packets[rng()%f.packets.size()].box;tablet::spatial::Window window{b.minX+1,b.minY+1,b.minX+3,b.minY+3};std::vector<uint32_t> expected;for(auto& a:f.packets)if(sp::hits(a.box,window))expected.push_back(a.span.ordinal);size_t j=0;auto selected=[&](const sp::Packet& a){emit(a);check(j<expected.size()&&expected[j++]==a.span.ordinal,"spatial selection exact");};auto q=sp::query(r.file,r.manifest,window,4096,s,noStop,selected);check(j==expected.size()&&q.hits==j,"spatial completeness");packets+=j;++comparisons;}}
static void randomTest(int seeds){Temp root;sp::Stats s;for(int i=0;i<seeds;++i){Fixture f(i+1,1+(i*7919)%7000);sp::Cache c(s);check(c.init(root.path),"init");auto match=Fixture::match;auto r=c.create(f.key,2,*f.ink,f.dx,f.dy,f.vertices,noStop,match);check(bool(r),"create");verify(*r,f,s,i,40);r.reset();c.close();const auto raw=s.rawSamples.load();check(c.init(root.path),"reopen cache");r=c.lookup(f.key,2,f.vertices,f.header,uint32_t(f.ink->samples.size()));check(bool(r),"durable lookup");verify(*r,f,s,i+100,20);check(s.rawSamples==raw,"no replay on direct seek");check(!c.lookup(f.key,1,f.vertices,f.header,uint32_t(f.ink->samples.size())),"stale durable revision");check(s.peakBytes<=sp::diskCeiling,"quota");}std::printf("PASS seeds=%d query_oracles=%llu exact_packets=%llu direct_pages=%llu builds=%llu hits=%llu peak_disk=%llu\n",seeds,(unsigned long long)comparisons,(unsigned long long)packets,(unsigned long long)reads,(unsigned long long)s.builds.load(),(unsigned long long)s.hits.load(),(unsigned long long)s.peakBytes.load());}
static void faults(){Temp root;sp::Stats s;sp::Cache c(s);Fixture f(99,4097,true);auto match=Fixture::match;auto create=[&](d::Revision r){return c.create(f.key,r,*f.ink,f.dx,f.dy,f.vertices,noStop,match);};auto lookup=[&](d::Revision r){return c.lookup(f.key,r,f.vertices,f.header,uint32_t(f.ink->samples.size()));};check(c.init(root.path),"init");auto r=create(0);check(bool(r)&&r->manifest.durable==0,"dirty create");r.reset();c.close();check(c.init(root.path)&&!lookup(2),"dirty not reopened");r=create(0);check(r&&c.promote(*r,2)&&r->manifest.durable==2,"promotion");r.reset();c.close();check(c.init(root.path),"reopen");r=lookup(2);check(bool(r),"promoted entry");auto emit=[](const sp::Packet&){};auto stop=[](){return true;};try{sp::direct(r->file,r->manifest,0,1,s,stop,emit);check(false,"cancel expected");}catch(sp::Failure f0){check(f0==sp::Failure::Cancelled,"cancel reason");}try{sp::query(r->file,r->manifest,{-1e9,-1e9,1e9,1e9},1,s,noStop,emit);check(false,"budget expected");}catch(sp::Failure f0){check(f0==sp::Failure::Capacity,"budget reason");}
    char filename[64];std::snprintf(filename,sizeof filename,"/ip-spans-v1/saved-%03zu.ipv",sp::Cache::slotFor(f.key));auto path=std::string(root.path)+filename;
    for(uint32_t page:{r->manifest.root.page,1u}){int fd=open(path.c_str(),O_RDWR);check(fd>=0,"corrupt open");uint8_t x=0;auto offset=off_t(page)*sp::pageBytes+8000;check(pread(fd,&x,1,offset)==1,"corrupt read");x^=1;check(pwrite(fd,&x,1,offset)==1,"corrupt write");close(fd);try{sp::direct(r->file,r->manifest,0,1,s,noStop,emit);check(false,"corruption accepted");}catch(sp::Failure f0){check(f0==sp::Failure::Invalid,"corruption reason");}r.reset();c.invalidate(sp::Cache::slotFor(f.key));r=create(2);check(bool(r),"corruption recovery");}
    check(truncate(path.c_str(),sp::pageBytes)==0,"truncate");r.reset();check(!lookup(2),"truncated cache rejected");r=create(2);check(bool(r),"truncate recovery");r.reset();
    struct rlimit old{},lim{};check(getrlimit(RLIMIT_FSIZE,&old)==0,"rlimit");lim=old;lim.rlim_cur=sp::pageBytes+17;auto sig=std::signal(SIGXFSZ,SIG_IGN);check(setrlimit(RLIMIT_FSIZE,&lim)==0,"limit set");r=create(2);check(setrlimit(RLIMIT_FSIZE,&old)==0,"limit restore");std::signal(SIGXFSZ,sig);check(!r&&s.io>0&&!lookup(2),"partial write rollback");r=create(2);check(bool(r),"write recovery");r.reset();
    for(int n=1;n<=120;n+=3){c.invalidate(sp::Cache::slotFor(f.key));int polls=0;auto cancel=[&]{return ++polls>=n;};auto x=c.create(f.key,2,*f.ink,f.dx,f.dy,f.vertices,cancel,match);check(!x&&!lookup(2),"cancelled build never published");}r=create(2);check(bool(r),"cancel recovery");r.reset();c.close();sp::Cache low(s,sp::pageBytes*2);check(low.init(root.path),"low init");check(!low.create(f.key,2,*f.ink,f.dx,f.dy,f.vertices,noStop,match)&&s.capacityFailures>0,"strict disk quota");std::puts("PASS dirty/reopen promotion, stale revision, CRC root/leaf, truncation, real partial write, 40 cancelled builds, capacity and recovery");}
static void identityAndEviction(){Temp root;sp::Stats stats;Fixture a(7,1000,true),b(8,1000,true);auto match=Fixture::match;
    constexpr uint64_t quota=20*sp::pageBytes;sp::Cache c(stats,quota);check(c.init(root.path),"identity init");auto create=[&](Fixture& f){return c.create(f.key,2,*f.ink,f.dx,f.dy,f.vertices,noStop,match);};auto lookup=[&](Fixture& f,const sp::Key& key){return c.lookup(key,2,f.vertices,f.header,uint32_t(f.ink->samples.size()));};
    auto r=create(a);check(bool(r),"first quota entry");r.reset();for(int i=0;i<5;++i){auto key=a.key;switch(i){case 0:key.doc[1]^=1;break;case 1:++key.id;break;case 2:++key.geometry;break;case 3:key.digest[0]^=1;break;case 4:key.mesh[0]^=1;break;}check(!lookup(a,key),"wrong source identity");}
    check(bool(lookup(a,a.key)),"original identity still valid");r=create(b);check(bool(r)&&stats.peakBytes<=quota&&stats.evictions>0,"quota eviction");check(!lookup(a,a.key),"evicted source cannot reappear");auto emit=[](const sp::Packet&){};for(auto [first,count]:std::array<std::pair<uint32_t,uint32_t>,4>{{{0,0},{0,129},{r->manifest.root.count,1},{UINT32_MAX,1}}}){try{sp::direct(r->file,r->manifest,first,count,stats,noStop,emit);check(false,"invalid direct range");}catch(sp::Failure why){check(why==sp::Failure::Invalid,"invalid extent reason");}}
    r.reset();c.close();check(c.init(root.path)&&bool(lookup(b,b.key))&&!lookup(a,a.key),"eviction survives reopen");std::puts("PASS five source-key mismatches, four invalid range extents, strict quota eviction and reopened ownership");}
static void scale(){for(size_t n:{1000,10000,100000}){Temp root;sp::Stats s;sp::Cache c(s);Fixture f(n,n,true);auto match=Fixture::match;check(c.init(root.path),"scale init");auto start=sp::Clock::now();auto r=c.create(f.key,2,*f.ink,f.dx,f.dy,f.vertices,noStop,match);check(bool(r),"scale build");auto build=sp::elapsed(start);auto raw=s.rawSamples.load();std::vector<uint64_t> times;uint32_t pages=0;for(int i=0;i<100;++i){auto emit=[](const sp::Packet&){};start=sp::Clock::now();auto q=sp::direct(r->file,r->manifest,r->manifest.root.count-128,128,s,noStop,emit);times.push_back(sp::elapsed(start));pages=std::max(pages,q.pages);}std::sort(times.begin(),times.end());check(s.rawSamples==raw,"no replay");std::printf("scale samples=%zu disk=%llu build_ms=%.3f direct128_p50_us=%.3f p95_us=%.3f max_pages=%u\n",n,(unsigned long long)s.bytes.load(),build/1e6,times[50]/1e3,times[94]/1e3,pages);}}
int main(int argc,char** argv){hashTest();if(argc>1&&std::string_view(argv[1])=="faults"){faults();identityAndEviction();}else if(argc>1&&std::string_view(argv[1])=="scale")scale();else randomTest(argc>1?std::atoi(argv[1]):24);}
